local _, T = ...
T:RegisterPage("convenience", {key = "market", label = "Auction values", order = 4.1, build = function(p)
    local cfg = function() return T.db.market end
    p:Section("Auction values", "Shows the lowest buyout from Tempus's own auction house scan on item tooltips, including stack estimates in Tempus bags. Prices are shared by all your characters on the realm. Listing prices are estimates, not completed sales.")
    p:Check(cfg, "tooltips", "Show auction estimates on item tooltips")
    p:Slider(cfg, "staleDays", "Mark prices stale after", 1, 14, 1, function(v) return v .. " days" end)
    p:Section("Scanning", "Open the auction house and click Tempus scan in the top-left corner of its window, or the button below. A scan reads every listing in one request and keeps the lowest buyout per item. The game allows one full scan about every 15 minutes.")
    p:Check(cfg, "autoScan", "Scan automatically when I open the auction house")
    p:Add(T.UI.W.Button("Scan auction house", function() T.Market:StartScan() end, "Reads the whole auction house once. Does not buy, sell or post anything.", 200))
    p:Section("Gear upgrades", "The Upgrades button in the top-left corner of the auction house window, or /tempus upgrades from anywhere, lists the best gear deals from your last scan: items above what you wear in that slot, that you can equip, ranked by how much your stats improve for the price, so a nearly free +1 does not top the list and gear with the wrong stats for your class is left out.")
    p:Add(T.UI.W.Button("Open upgrades list", function() T.Market:ToggleUpgrades() end, "Opens the list from your last scan. It works anywhere; you do not need the auction house open. Drag it to move it. Also /tempus upgrades.", 200))
    p:Dropdown(cfg, "upgradeSort", "Rank upgrades by", { { "VALUE", "Best value (stats for the price)" }, { "BIGGEST", "Biggest upgrade" }, { "CHEAPEST", "Cheapest first" } })
    p:Slider(cfg, "upgradeMinGain", "Minimum item level gain", 1, 30, 1, function(v) return "+" .. v end)
    p:Slider(cfg, "upgradeMaxGold", "Maximum price (gold, 0 = no limit)", 0, 1000, 5, function(v) return v == 0 and "No limit" or (v .. "g") end, "Hides upgrades that cost more than this per item. You can also type a price in the upgrades window.")
    p:Check(cfg, "upgradeAffordable", "Only show upgrades I can afford")
    p:Check(cfg, "upgradeUseAHFilters", "Use the auction house filters", "The list follows the rarity and level range set in the auction house search filter, once you have opened the auction house this session.")
    p:Paragraph("Items with no scan data show 'No scanned price'; older prices are marked stale. Re-hover an item after a scan to see its updated estimate.")
end})
